// Wspólny model poziomu dla Polski i zagranicy.
// pyramidLevel = miejsce w krajowej piramidzie; leaguePrestige/leagueTier =
// wspólna ranga ligi; globalTier = wspólna ranga klubu wynikająca z OVR.
// Stare tier/foreignTier pozostają tylko dla zgodności z zapisami i modułami,
// które nie zostały jeszcze przeniesione na pola kanoniczne.
const LEAGUE_PRESTIGE_ORDER=['A+','A','A-','B+','B','B-','C+','C','C-','D+','D','D-','E+','E','E-','F','F-'];
const prestigeToLeagueTier=prestige=>{
  const index=LEAGUE_PRESTIGE_ORDER.indexOf(prestige);
  return index>=0?index+1:LEAGUE_PRESTIGE_ORDER.length;
};
const globalClubTier=strength=>{
  const ovr=Number(strength)||0;
  if(ovr>=92)return 1;
  if(ovr>=84)return 2;
  if(ovr>=74)return 3;
  if(ovr>=65)return 4;
  if(ovr>=57)return 5;
  if(ovr>=50)return 6;
  if(ovr>=45)return 7;
  if(ovr>=36)return 8;
  if(ovr>=25)return 9;
  if(ovr>=19)return 10;
  if(ovr>=13)return 11;
  if(ovr>=4)return 12;
  return 13;
};
const databaseStableHash=text=>{
  let value=2166136261;
  for(const char of String(text||'')){
    value^=char.codePointAt(0);
    value=Math.imul(value,16777619);
  }
  return value>>>0;
};
const stableClubOvr=(club,min,max)=>min+(databaseStableHash(`${club.name}|${club.region}|${club.leagueName}|${club.group||''}`)%(max-min+1));
const cClassTwoOvr=new Set(['Kłodnica Gliwice','Start Kleszczów','Trampkarz 22 Biskupice Zabrze']);
const polishLeagueScale=club=>{
  const league=String(club.leagueName||'').toLocaleLowerCase('pl-PL');
  if(/klasa\s*c/.test(league))return {key:'C',min:4,max:12,prestige:'F-',finance:1};
  if(/klasa\s*b/.test(league))return {key:'B',min:8,max:18,prestige:'F',finance:1};
  if(/klasa\s*a/.test(league))return {key:'A',min:15,max:25,prestige:'E-',finance:1};
  if(/okręg/.test(league))return {key:'OKR',min:25,max:35,prestige:'E',finance:1};
  if(/^v liga|\bliga v\b/.test(league))return {key:'V',min:35,max:44,prestige:'E+',finance:1};
  if(/\biii liga\b/.test(league))return {key:'III',prestige:'D',finance:1};
  if(/\biv liga\b/.test(league))return {key:'IV',prestige:'D-',finance:1};
  if(/ii liga/.test(league))return {key:'II',prestige:'C-',finance:1};
  if(/i liga/.test(league))return {key:'I',prestige:'C',finance:1};
  if(/ekstraklasa/.test(league))return {key:'ESA',prestige:'B',finance:1};
  return null;
};
CLUBS.forEach(club=>{
  const scale=polishLeagueScale(club);
  if(scale?.min){
    club.strength=scale.key==='C'&&cClassTwoOvr.has(club.name)
      ?2
      :stableClubOvr(club,scale.min,scale.max);
  }
  const prestige=scale?.prestige||'F-';
  Object.assign(club,{
    leaguePrestige:prestige,
    leagueTier:prestigeToLeagueTier(prestige),
    leagueFinance:scale?.finance??1,
    globalTier:globalClubTier(club.strength)
  });
});

// Twardy trait instytucjonalny. Te kluby po znalezieniu się poza
// Ekstraklasą zachowują zaplecze krajowej potęgi aż do powrotu.
const NATIONAL_POWERHOUSE_CLUBS=new Set([
  'Legia Warszawa','Raków Częstochowa','Widzew Łódź','Lech Poznań',
  'Górnik Zabrze','GKS Katowice','Jagiellonia Białystok','Pogoń Szczecin',
  'Wisła Kraków'
]);
const isNationalPowerhouseClub=club=>!!club&&!Number.isFinite(club.foreignTier)&&NATIONAL_POWERHOUSE_CLUBS.has(club.name);

// Pełna baza pierwszych zespołów 2026/27 z 90minut.pl.
// Rezerwy są świadomie pominięte. pyramidLevel: 1 = Ekstraklasa, 10 = Klasa C.
// OVR: C 4–12 (trzy kluby 2), B 8–18, A 15–25, okręgowa 25–35, V 35–44.
// Uśpiony schemat rozwoju klubu. Pola istnieją w każdym klubie, ale wersja
// Rdzeń kariery nie odczytuje ich jeszcze ani nie uwzględnia w symulacji.
CLUBS.forEach(club=>Object.assign(club,{
  coach:null,
  fans:null,
  finances:null,
  traits:isNationalPowerhouseClub(club)?['KRAJOWA POTĘGA']:[],
  training:null
}));

