function foreignLeagueReference(country,league){
  const key=String(country||'').toLocaleUpperCase('pl-PL')+'|'+String(league||'');
  return FOREIGN_LEAGUE_REFERENCE[key]||null;
}
function calibratedLowerForeignTier(overall){
  if(overall>=50)return 5;
  if(overall>=36)return 6;
  if(overall>=19)return 7;
  return 8;
}
function applyForeignLeagueReferences(clubs){
  const grouped=new Map();
  clubs.forEach(club=>{
    const key=String(club.country||'').toLocaleUpperCase('pl-PL')+'|'+String(club.league||'');
    if(!grouped.has(key))grouped.set(key,[]);
    grouped.get(key).push(club);
  });
  grouped.forEach((members,key)=>{
    const reference=FOREIGN_LEAGUE_REFERENCE[key];
    if(!reference)return;
    members.forEach(club=>{
      club.leagueReferenceOverall=reference.overall;
      club.leagueReferencePrestige=reference.prestige;
    });
    const flexible=members.filter(club=>Number(club.foreignTier)>4)
      .sort((a,b)=>b.strength-a.strength||a.name.localeCompare(b.name,'pl'));
    if(!flexible.length)return;
    // T1-T4 pozostają dokładnie nietknięte. Dla niższych klubów wartość ligi
    // wyznacza środek rozkładu, a dotychczasowa kolejność zachowuje hierarchię.
    // Sufit 64 gwarantuje, że kalibracja nie dopisze nowych klubów do T1-T4.
    const center=Math.max(1,Math.min(60,Math.round(reference.overall)));
    const spread=center>=50?5:center>=36?4:center>=19?3:Math.min(3,Math.max(1,center-1));
    flexible.forEach((club,index)=>{
      const rank=flexible.length===1?0:1-(index/(flexible.length-1))*2;
      club.strength=Math.max(1,Math.min(64,Math.round(center+rank*spread)));
      club.foreignTier=calibratedLowerForeignTier(club.strength);
      club.tier=Math.min(8,Math.max(2,10-club.foreignTier));
      club.ovrCalibrationSource='league-reference-2026-27';
    });
  });
}

applyForeignLeagueReferences(GAME_DATA.foreignClubs);


// Pełny model lig zagranicznych: hierarchia rozgrywek oraz zaakceptowane
// parametry prestiżu, poziomu sportowego i finansów. Wszystkie wartości są
// wyliczane raz przy starcie na podstawie klubów faktycznie obecnych w bazie.
function buildForeignLeagueModel(clubs){
  const closedLeagues=new Set([
    'USA|USL Championship','USA|USL League One','USA|Cosmopolitan Soccer League',
    'USA|American Premier Soccer League','USA|New Jersey Soccer Association',
    'USA|ZPKP-PASA (Connecticut)','USA|Polish-American Soccer Association',
    'Meksyk|Liga de Expansión MX','Kanada|Canadian Premier League',
    'Nowa Zelandia|New Zealand National League','Brunei|Brunei Super League'
  ]);
  const prestigeOverrides={
    'Anglia|Premier League':'A+','Hiszpania|LaLiga EA Sports':'A+',
    'Niemcy|Bundesliga':'A','Włochy|Serie A':'A','Francja|Ligue 1':'A-',
    'Portugalia|Liga Portugal Betclic':'B+','Holandia|Eredivisie':'B+',
    'Brazylia|Campeonato Brasileiro Série A':'B+','Argentyna|Liga Profesional':'B+',
    'Turcja|Süper Lig':'B+','Arabia Saudyjska|Saudi Pro League':'B',
    'USA|MLS':'B','Meksyk|Liga MX':'B','Belgia|Jupiler Pro League':'B'
  };
  // Mnożnik koryguje stary kalkulator kontraktów, nie zastępuje go.
  // 1.00 zachowuje dotychczasowy wzór; wartości poniżej/powyżej jedności
  // odpowiednio ścinają albo podbijają jego wynik.
  const countryFinance={
    'Arabia Saudyjska':3.00,'Katar':2.20,
    'Turcja':1.50,'Chiny':1.50,
    'Tajwan':2.00,'Hongkong':2.00,'Wietnam':2.00
  };
  const prestigeFromSport=sport=>sport>=90?'A+':sport>=86?'A':sport>=82?'A-':
    sport>=78?'B+':sport>=72?'B':sport>=66?'B-':sport>=60?'C+':sport>=54?'C':
    sport>=48?'C-':sport>=42?'D+':sport>=36?'D':sport>=30?'D-':
    sport>=24?'E+':sport>=18?'E':sport>=10?'E-':sport>=4?'F':'F-';
  const grouped=new Map();
  clubs.forEach(club=>{
    const key=club.country+'|'+club.league;
    if(!grouped.has(key)) grouped.set(key,[]);
    grouped.get(key).push(club);
  });
  const byCountry=new Map();
  grouped.forEach((members,key)=>{
    const sample=members[0];
    const average=members.reduce((sum,club)=>sum+club.strength,0)/members.length;
    const reference=foreignLeagueReference(sample.country,sample.league);
    const stat={key,country:sample.country,league:sample.league,zone:sample.zone,
      average,sportLevel:reference?.overall??average,referencePrestige:reference?.prestige||null,
      count:members.length,members};
    if(!byCountry.has(sample.country)) byCountry.set(sample.country,[]);
    byCountry.get(sample.country).push(stat);
  });
  const transitions={};
  const config={};
  byCountry.forEach((stats,country)=>{
    stats.sort((a,b)=>b.sportLevel-a.sportLevel||b.average-a.average||b.count-a.count||a.league.localeCompare(b.league,'pl'));
    const levels=[];
    stats.forEach(stat=>{
      const current=levels[levels.length-1];
      if(!current||current.anchor-stat.sportLevel>4) levels.push({anchor:stat.sportLevel,leagues:[stat]});
      else current.leagues.push(stat);
    });
    levels.forEach((level,index)=>{
      level.leagues.forEach(stat=>{
        const sport=Math.round(stat.sportLevel);
        const finance=countryFinance[country]??((stat.zone==='Afryka'&&country!=='Egipt') ? 0.50 : 1);
        config[stat.key]={
          leagueId:'INT:'+stat.key,domesticLevel:index+1,clubs:stat.count,
          sportLevel:sport,prestige:stat.referencePrestige||prestigeOverrides[stat.key]||prestigeFromSport(sport),
          finance
        };
      });
      if(index===0) return;
      const upper=levels[index-1].leagues.slice()
        .sort((a,b)=>b.count-a.count||b.average-a.average||a.league.localeCompare(b.league,'pl'))[0];
      level.leagues.forEach(stat=>{
        if(!closedLeagues.has(stat.key)) transitions[stat.key]={to:upper.league};
      });
    });
  });
  closedLeagues.forEach(key=>{ if(grouped.has(key)) transitions[key]={to:null,closed:true}; });
  return {transitions,config};
}
const FOREIGN_LEAGUE_MODEL=buildForeignLeagueModel(GAME_DATA.foreignClubs);
GAME_DATA.foreignClubs.forEach(club=>{
  const leagueConfig=FOREIGN_LEAGUE_MODEL.config[club.country+'|'+club.league];
  Object.assign(club,{
    competitionKey:leagueConfig?.leagueId||('INT:'+club.country+'|'+club.league),
    globalTier:globalClubTier(club.strength),
    leagueSportLevel:leagueConfig?.sportLevel??club.strength,
    leaguePrestige:leagueConfig?.prestige||'F',
    leagueTier:prestigeToLeagueTier(leagueConfig?.prestige||'F'),
    leagueFinance:leagueConfig?.finance??1,
    coach:club.coach??null,
    fans:club.fans??null,
    finances:club.finances??null,
    traits:Array.isArray(club.traits)?club.traits:[],
    training:club.training??null
  });
});
// Niezmienny identyfikator klubu. Nazwa i region nie zawsze są unikalne
// (w polskiej bazie istnieją dwa takie dublety), a competitionKey zmienia
// się po awansie. worldId zostaje więc z klubem przez całą karierę.
CLUBS.filter(club=>!club.reserve).forEach(club=>{
  club.worldId=`PL:${club.region||''}|${club.name}|${club.competitionKey||''}`;
});
GAME_DATA.foreignClubs.forEach(club=>{
  club.worldId=`INT:${club.country||''}|${club.name}|${club.league||''}`;
});

// ============================================================
// PPS LEAGUE ENGINE 1.0
// Wspólny, deterministyczny rdzeń rozgrywek ligowych. Liga gracza
// zachowuje terminarz i wyniki kolejek; ligi tła używają tego samego
// cienia meczu, ale po aktualizacji tabeli wyrzucają pojedyncze wyniki.
// ============================================================
window.PPSLeagueEngine=(()=>{
  const clamp=(value,min,max)=>Math.min(max,Math.max(min,value));
  const hash=text=>{
    let value=2166136261;
    for(const char of String(text||'')){
      value^=char.codePointAt(0);
      value=Math.imul(value,16777619);
    }
    return value>>>0;
  };
  const createRandom=seedText=>{
    let seed=hash(seedText)||0x9e3779b9;
    const next=()=>{
      seed^=seed<<13; seed^=seed>>>17; seed^=seed<<5;
      return (seed>>>0)/4294967296;
    };
    next.int=(min,max)=>min+Math.floor(next()*(max-min+1));
    next.pick=array=>array[Math.floor(next()*array.length)];
    return next;
  };
  const logistic=value=>1/(1+Math.exp(-value));
  const average=values=>values.length?values.reduce((sum,value)=>sum+value,0)/values.length:0;
  const leagueStats=teams=>{
    const values=teams.filter(team=>!team.virtual).map(team=>Number(team.strength)||0);
    const pool=values.length?values:teams.map(team=>Number(team.strength)||0);
    const mean=average(pool);
    const variance=average(pool.map(value=>(value-mean)**2));
    // Nie ściskamy bardzo wyrównanej ligi do mikroskopijnego rozrzutu.
    // Dawniej 2–3 OVR potrafiły w takim otoczeniu niemal gwarantować serię
    // zwycięstw i kolejne awanse. Podłoga 3 OVR zostawia przewagę mocniejszym,
    // ale utrzymuje realną wariancję pojedynczego sezonu.
    return {mean,spread:clamp(Math.sqrt(variance)||3,3,12)};
  };
  function generateRoundRobin(teams,doubleRound=true){
    const list=teams.slice();
    if(list.length%2!==0) list.push({bye:true,id:'__BYE__'});
    const rounds=[];
    let rotation=list.slice();
    for(let round=0;round<rotation.length-1;round++){
      const matches=[];
      for(let index=0;index<rotation.length/2;index++){
        const first=rotation[index],second=rotation[rotation.length-1-index];
        if(first.bye||second.bye) continue;
        matches.push(round%2===0?{home:first,away:second}:{home:second,away:first});
      }
      rounds.push(matches);
      rotation=[rotation[0],rotation[rotation.length-1],...rotation.slice(1,-1)];
    }
    if(!doubleRound) return rounds;
    return rounds.concat(rounds.map(matches=>matches.map(match=>({home:match.away,away:match.home}))));
  }
  const emptyRow=team=>({
    id:team.id,name:team.name,strength:team.strength,virtual:!!team.virtual,
    played:0,won:0,drawn:0,lost:0,gf:0,ga:0,points:0
  });
  const createTable=teams=>Object.fromEntries(teams.map(team=>[team.id,emptyRow(team)]));
  function updateTable(table,home,away,homeGoals,awayGoals){
    const h=table[home.id],a=table[away.id];
    h.played++; a.played++;
    h.gf+=homeGoals; h.ga+=awayGoals;
    a.gf+=awayGoals; a.ga+=homeGoals;
    if(homeGoals>awayGoals){h.won++;h.points+=3;a.lost++;}
    else if(homeGoals<awayGoals){a.won++;a.points+=3;h.lost++;}
    else{h.drawn++;a.drawn++;h.points++;a.points++;}
  }
  const sortedTable=table=>Object.values(table).sort((a,b)=>
    b.points-a.points || (b.gf-b.ga)-(a.gf-a.ga) || b.gf-a.gf ||
    b.strength-a.strength || a.name.localeCompare(b.name,'pl')
  ).map((row,index)=>({...row,place:index+1,gd:row.gf-row.ga}));
  function resolveShadowMatch(home,away,stats,random){
    // Odchudzony potomek silnika Ekstraklasa Draft: inicjatywa -> jakość
    // sytuacji -> wykończenie. OVR normalizujemy rozrzutem ligi, dzięki
    // czemu trzy punkty w Klasie C znaczą więcej niż trzy w LaLiga.
    const homeRelative=(home.strength-stats.mean)/stats.spread;
    const awayRelative=(away.strength-stats.mean)/stats.spread;
    const relativeGap=homeRelative-awayRelative;
    const homeInitiative=clamp(logistic(relativeGap*.58+.16),.20,.80);
    let homeGoals=0,awayGoals=0;
    const actions=22+random.int(0,4);
    for(let action=0;action<actions;action++){
      const homeAttacks=random()<homeInitiative;
      const attackerRelative=homeAttacks?homeRelative:awayRelative;
      const defenderRelative=homeAttacks?awayRelative:homeRelative;
      const qualityEdge=clamp((attackerRelative-defenderRelative)*.038,-.07,.07);
      const highQuality=random()<clamp(.25+qualityEdge,.12,.42);
      const conversion=clamp((highQuality?.205:.072)+qualityEdge*.55,.025,.32);
      if(random()<conversion){
        if(homeAttacks)homeGoals++; else awayGoals++;
      }
    }
    return {homeGoals:Math.min(9,homeGoals),awayGoals:Math.min(9,awayGoals)};
  }
  function simulateLeague({teams,seed,keepRounds=false,doubleRound=true}){
    const random=createRandom(seed);
    const stats=leagueStats(teams);
    const table=createTable(teams);
    const schedule=generateRoundRobin(teams,doubleRound);
    const rounds=[];
    schedule.forEach((matches,roundIndex)=>{
      const records=[];
      matches.forEach(match=>{
        const result=resolveShadowMatch(match.home,match.away,stats,random);
        updateTable(table,match.home,match.away,result.homeGoals,result.awayGoals);
        if(keepRounds)records.push({
          homeId:match.home.id,home:match.home.name,awayId:match.away.id,away:match.away.name,
          homeGoals:result.homeGoals,awayGoals:result.awayGoals
        });
      });
      if(keepRounds)rounds.push({round:roundIndex+1,matches:records});
    });
    return {table:sortedTable(table),rounds,stats,matches:schedule.reduce((sum,round)=>sum+round.length,0)};
  }
  return Object.freeze({hash,createRandom,generateRoundRobin,resolveShadowMatch,simulateLeague,leagueStats});
})();

